# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> STATIC
_static_start_watcher_kind() {
    cat <<-'ARGCEOF'
	polling	Periodically checks for changes
	recommended	Uses the operating system's recommended watcher
	none	Disables watching
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
_choice_max_diagnostics() {
    printf 'none\n'
}

_choice_since_ref() {
    git rev-parse --git-dir >/dev/null 2>&1 || return 0
    printf 'HEAD\n'
    git for-each-ref --count=500 --format='%(refname:short)' refs/heads refs/tags refs/remotes 2>/dev/null
}

_choice_vcs_default_branch() {
    git for-each-ref --count=500 --format='%(refname:short)' refs/heads refs/remotes 2>/dev/null
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
